<script>
document.addEventListener('DOMContentLoaded', function() {
    // Récupérer tous les paths (régions) - dans VOTRE cas, ce sont les <path>
    let paths = document.querySelectorAll('svg path');
    let regions = document.getElementById("regions");
    let listeRegions = [];
    
    console.log('Nombre de régions trouvées:', paths.length);
    
    // Vérifier qu'on a bien l'élément suivi-souris
    let suiviSouris = document.getElementById("suivi-souris");
    if (!suiviSouris) {
        suiviSouris = document.createElement('div');
        suiviSouris.id = "suivi-souris";
        suiviSouris.style.cssText = `
            position: fixed;
            display: none;
            background: white;
            border-radius: 10px;
            padding: 12px 18px;
            min-width: 220px;
            box-shadow: 0 5px 20px rgba(0,0,0,0.15);
            border: 2px solid #000000;
            z-index: 1000;
            pointer-events: none;
            font-family: Arial, sans-serif;
            font-size: 14px;
        `;
        document.body.appendChild(suiviSouris);
    }
    
    for (let i = 0; i < paths.length; i++) {
        listeRegions.push(paths[i]);
        
        // Récupérer le nom de la région
        let regionName = paths[i].getAttribute('name') || 
                        paths[i].getAttribute('id') || 
                        'Région ' + (i + 1);
        
        paths[i].addEventListener("mousemove", (e) => {
            let mouseY = e.clientY;
            let mouseX = e.clientX;
            
            // Afficher le nom de la région
            suiviSouris.innerHTML = regionName;
            suiviSouris.style.display = "block";
            
            suiviSouris.style.top = (mouseY + 15) + "px";
            suiviSouris.style.left = (mouseX + 15) + "px";
        });
        
        paths[i].addEventListener("mouseout", (e) => {
            suiviSouris.style.display = "none";
        });
        
        // Ajouter effet visuel au survol
        paths[i].addEventListener("mouseover", () => {
            paths[i].style.opacity = "0.7";
            paths[i].style.transition = "opacity 0.3s";
        });
        
        paths[i].addEventListener("mouseout", () => {
            paths[i].style.opacity = "1";
        });
    }

    // Trier les régions par ID
    listeRegions.sort(function (a, b) {
        let idA = a.getAttribute('id') || '';
        let idB = b.getAttribute('id') || '';
        
        if (idA < idB) {
            return -1;
        } else if (idA > idB) {
            return 1;
        }
        return 0;
    });

    // Créer la liste des régions (si l'élément regions existe)
    if (regions) {
        for (let i = 0; i < listeRegions.length; i++) {
            let lien = document.createElement("a");
            
            // Récupérer le lien du parent <a> si il existe
            let parentLink = listeRegions[i].closest('a');
            if (parentLink) {
                lien.href = parentLink.getAttribute("href") || "#";
            } else {
                lien.href = "#";
            }
            
            lien.target = "_blank";
            
            // Utiliser le nom ou l'ID pour l'affichage
            let regionName = listeRegions[i].getAttribute('name') || 
                           listeRegions[i].getAttribute('id') || 
                           'Région ' + (i + 1);
            lien.innerHTML = regionName;
            
            lien.addEventListener("mouseover", () => {
                listeRegions[i].classList.add("region-carte-hover");
            });
            
            lien.addEventListener("mouseout", () => {
                listeRegions[i].classList.remove("region-carte-hover");
            });
            
            regions.appendChild(lien);
        }
    }
});
</script>
